import pytest

if pytest.use_correct:
    from correct_python_programs.shortest_paths import shortest_paths
else:
    from python_programs.shortest_paths import shortest_paths


def test_attack_1():
    """Unreachable source-only node must be present with inf."""
    graph = {
        ("A", "B"): 1,
        ("C", "D"): 10,
    }
    result = shortest_paths("A", graph)
    expected = {"A": 0, "B": 1, "C": float("inf"), "D": float("inf")}
    assert result == expected


def test_attack_2():
    """Source not in graph: all graph nodes present with inf."""
    graph = {
        ("X", "Y"): 5,
    }
    result = shortest_paths("Z", graph)
    expected = {"X": float("inf"), "Y": float("inf"), "Z": 0}
    assert result == expected


def test_attack_3():
    """Source is a sink: its predecessor (source-only) must be present."""
    graph = {
        ("A", "B"): 1,
    }
    result = shortest_paths("B", graph)
    expected = {"A": float("inf"), "B": 0}
    assert result == expected


def test_attack_4():
    """Reachable chain plus disconnected edge; source-only D must be present."""
    graph = {
        ("A", "B"): 2,
        ("B", "C"): 3,
        ("D", "E"): 1,
    }
    result = shortest_paths("A", graph)
    expected = {
        "A": 0,
        "B": 2,
        "C": 5,
        "D": float("inf"),
        "E": float("inf"),
    }
    assert result == expected


def test_attack_5():
    """Negative edge with unreachable source-only node."""
    graph = {
        ("A", "B"): 4,
        ("A", "C"): 3,
        ("C", "B"): -2,
        ("D", "E"): -5,
    }
    result = shortest_paths("A", graph)
    expected = {
        "A": 0,
        "B": 1,
        "C": 3,
        "D": float("inf"),
        "E": float("inf"),
    }
    assert result == expected


def test_attack_6():
    """Long chain plus disconnected component; source-only X must be present."""
    graph = {
        ("A", "B"): 1,
        ("B", "C"): 2,
        ("C", "D"): 3,
        ("X", "Y"): 1,
    }
    result = shortest_paths("A", graph)
    expected = {
        "A": 0,
        "B": 1,
        "C": 3,
        "D": 6,
        "X": float("inf"),
        "Y": float("inf"),
    }
    assert result == expected

